problems.solutionCode:
import { useEffect, useRef, useState } from 'react';
export function ClaimReferenceField({ errorMessage = '' }: { errorMessage?: string }) {
  const [visible, setVisible] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (visible) inputRef.current?.focus();
  }, [visible]);
  function checkClaim() {
    if (visible) {
      inputRef.current?.focus();
      return;
    }
    setVisible(true);
  }
  return <section><button type="button" onClick={checkClaim}>Check claim</button>{visible ? <label>Claim reference<input ref={inputRef} aria-label="Claim reference" /></label> : null}{errorMessage ? <p role="alert">{errorMessage}</p> : null}</section>;
}

