import { useEffect, useRef, useState } from 'react';
export function BinScanCapture({ onCapture }: { onCapture: (code: string) => void }) {
  const [visible, setVisible] = useState(false);
  const [code, setCode] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (visible) inputRef.current?.focus();
  }, [visible]);
  function startScan() {
    setVisible(true);
  }
  function capture(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const normalized = code.trim();
    if (normalized) onCapture(normalized);
  }
  return <form onSubmit={capture}><button type="button" onClick={startScan}>Start scan</button>{visible ? <label>Bin code<input ref={inputRef} aria-label="Bin code" value={code} onChange={(event) => setCode(event.target.value)} /></label> : null}<button type="submit">Capture bin</button></form>;
}

