problems.solutionCode:
import { useEffect, useRef, useState } from 'react';
export function ActivityFeed({ items, onLoadOlder }: { items: string[]; onLoadOlder: () => void }) {
  const [loaded, setLoaded] = useState(false);
  const firstEntryRef = useRef<HTMLLIElement>(null);
  const pendingScrollRef = useRef(false);
  useEffect(() => {
    if (pendingScrollRef.current && items.length > 0) {
      firstEntryRef.current?.scrollIntoView?.();
      pendingScrollRef.current = false;
    }
  }, [items]);
  function loadOlder() {
    pendingScrollRef.current = true;
    onLoadOlder();
    setLoaded(true);
  }
  return <section><button type="button" onClick={loadOlder}>Load older activity</button><output aria-label="Activity count">{items.length}</output>{items.length === 0 ? <p>No activity</p> : <ul>{items.map((item, index) => <li ref={index === 0 ? firstEntryRef : null} key={`${item}-${index}`}>{item}</li>)}</ul>}{loaded ? <p role="status">Older activity requested</p> : null}</section>;
}

