import { useRef, useState } from 'react';
export function FilterPanel({ filters }: { filters: string[] }) {
  const [open, setOpen] = useState(false);
  const [panelVisible, setPanelVisible] = useState(false);
  const fieldRef = useRef<HTMLInputElement>(null);
  function togglePanel() {
    const nextOpen = !open;
    setOpen(nextOpen);
    setPanelVisible(nextOpen);
    if (nextOpen) fieldRef.current?.focus();
  }
  return <section><button type="button" onClick={togglePanel}>Show filters</button>{panelVisible ? <div><button type="button" onClick={togglePanel}>Close filters</button>{filters.length ? filters.map((filter) => <label key={filter}>{filter}<input ref={fieldRef} aria-label={filter} /></label>) : <p>No filters available</p>}</div> : null}</section>;
}

