import { useEffect, useRef, useState } from 'react';
export function FilterPanel({ filters }: { filters: string[] }) {
  const [open, setOpen] = useState(false);
  const fieldRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (open && filters.length > 0) fieldRef.current?.focus();
  }, [open, filters.length]);
  function openPanel() {
    setOpen(true);
  }
  return <section><button type="button" onClick={openPanel}>Show filters</button>{open ? <div><button type="button" onClick={() => setOpen(false)}>Close filters</button>{filters.length ? filters.map((filter, index) => <label key={filter}>{filter}<input ref={index === 0 ? fieldRef : null} aria-label={filter} /></label>) : <p>No filters available</p>}</div> : null}</section>;
}

